code.formula:
@Command([EditDocument];"1");

@If (EmNo= ""; @Return(@Do(@Command([EditGotoField];"EmNo") ;@Prompt([Ok];"Missing Value"; "Please enter the employee number!")));"");
@If (EmName= ""; @Return(@Do(@Command([EditGotoField];"EmName") ;@Prompt([Ok];"Missing Value"; "Please enter the employee name!")));"");
@If (EmComp= ""; @Return(@Do(@Command([EditGotoField];"EmComp") ;@Prompt([Ok];"Missing Value"; "Please enter the employee company!")));"");
@If (EmDesg= ""; @Return(@Do(@Command([EditGotoField];"EmDesg") ;@Prompt([Ok];"Missing Value"; "Please enter the employee designation!")));"");
@If (EmDept= ""; @Return(@Do(@Command([EditGotoField];"EmDept") ;@Prompt([Ok];"Missing Value"; "Please enter the employee department!")));"");
@If (EmDateJoin= ""; @Return(@Do(@Command([EditGotoField];"EmDateJoin") ;@Prompt([Ok];"Missing Value"; "Please select the Date Joined!")));"");
@If (EmComYear= ""; @Return(@Do(@Command([EditGotoField];"EmComYear") ;@Prompt([Ok];"Missing Value"; "Please select the Commencement year of current position!")));"");
@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please enter HOD Name!")));"");

FIELD CA :="Submitted";
FIELD subby := @V3UserName;
FIELD subdt := @Now;

@Command([FileSave]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (EmpEmail = ""; @Return(@Do(@Command([EditGotoField];"EmpEmail") ;@Prompt([Ok];"Missing Value"; "Please select the Employee email!")));"");
@If (AppBy = ""; @Return(@Do(@Command([EditGotoField];"AppBy") ;@Prompt([Ok];"Missing Value"; "Please select your appraise email!")));"");

FIELD CA :="Reviewed";
FIELD subby2 := @V3UserName;
FIELD subdt2 := @Now;

@MailSend(EmpEmail:AppBy;HOD;NULL;"New Appraisal for " + EmName + " - Submitted." ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

