@If (MS2= ""; @Return(@Do(@Command([EditGotoField];"MS2") ;@Prompt([Ok];"Missing Value"; "Please enter your score!")));"");
@If (MS3= ""; @Return(@Do(@Command([EditGotoField];"MS3") ;@Prompt([Ok];"Missing Value"; "Please enter KRAKPI score!")));"");
@If (EmpComments = ""; @Return(@Do(@Command([EditGotoField];"EmpComments") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
