@SetField("TA2";@Sum(@Attachments));

@Command([FileSave]);

@If(TA2 < 1;  @Return(@Do(@Command([EditGotoField];"KRAS") ;@Prompt([Ok];"Missing Value"; "Please attach your KRAKPI sheet before proceeding!")));"");

FIELD EmpName 	:= @V3UserName;
FIELD EmpDate 		:=@Today;
