@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (KS= ""; @Return(@Do(@Command([EditGotoField];"KS") ;@Prompt([Ok];"Missing Value"; "Please select at least one training!")));"");
@If (Rej = "1" & Comment1_1 = ""; @Return(@Do(@Command([EditGotoField];"Comment1_1") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
@If (Rej = "2" & Comment2_1 = ""; @Return(@Do(@Command([EditGotoField];"Comment1_1") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
@If (Rej = "3" & Comment3_1 = ""; @Return(@Do(@Command([EditGotoField];"Comment1_1") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");

@If(Rev="Yes" & Revi = "";@Return(@Do(@Command([EditGotoField];"Revi") ;@Prompt([Ok];"Missing Value"; "Please enter your Justification!")));"");
@If(Pro="Yes" & Promo = "";@Return(@Do(@Command([EditGotoField];"Promo") ;@Prompt([Ok];"Missing Value"; "Please enter your Justification!")));"");

@If (AppComments = "" & Comment1_1 = ""; @Return(@Do(@Command([EditGotoField];"AppComments") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");

@SetField("TA2";@Sum(@Attachments));

@Command([FileSave]);

@If(Rev="Yes" & TA2 < 2;@Return(@Do(@Command([EditGotoField];"Revi") ;@Prompt([Ok];"Missing Value"; "Please attach your Justification file!")));"");
@If(Pro="Yes" & TA2 < 2;@Return(@Do(@Command([EditGotoField];"Promo") ;@Prompt([Ok];"Missing Value"; "Please attach your Justification file!")));"");
@If(Rev="Yes" & Pro="Yes" & TA2 < 3;@Return(@Do(@Command([EditGotoField];"Prom") ;@Prompt([Ok];"Missing Value"; "Please attach your Justification file!")));"");

FIELD AppName 	:= @V3UserName;
FIELD AppDate 		:=@Today;
FIELD CA					:="ApprovedApp";

@MailSend(HOD;AppBy;NULL;"Appraisal for " + EmName + " - Completed by Appraiser.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (HODT != "" & HODT1 = ""; @Return(@Do(@Command([EditGotoField];"HODT1") ;@Prompt([Ok];"Missing Value"; "Please enter Section 2 Score!")));"");
@If (HODT != "" & HODT2 = ""; @Return(@Do(@Command([EditGotoField];"HODT2") ;@Prompt([Ok];"Missing Value"; "Please enter Section 3 Score!")));"");
@If (HODT != "" & HODT3 = ""; @Return(@Do(@Command([EditGotoField];"HODT3") ;@Prompt([Ok];"Missing Value"; "Please enter Section 4 Score!")));"");
@If (HODComments = "" & Comment1 = ""; @Return(@Do(@Command([EditGotoField];"HODComments") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");

FIELD HODName 		:= @V3UserName;
FIELD HODDate 			:=@Today;
