@MailSend(SendHR;HOD:AppBy:EmpEmail;NULL;"Appraisal for " + EmName + " - Accepted by HOD.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (Rej = "" & Comment1 = ""; @Return(@Do(@Command([EditGotoField];"Comment1") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
@If (Rej = "1" & Comment2 = ""; @Return(@Do(@Command([EditGotoField];"Comment2") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
@If (Rej = "2" & Comment3 = ""; @Return(@Do(@Command([EditGotoField];"Comment3") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");
@If (Rej = "3" & HODComments = ""; @Return(@Do(@Command([EditGotoField];"HODComments") ;@Prompt([Ok];"Missing Value"; "Please enter your Comments!")));"");

FIELD HODName 		:= @V3UserName;
FIELD HODDate 			:=@Today;
FIELD CA						:="Rejected";
@SetField("Rej";@If(Rej = "";"1";Rej = "1";"2";Rej = "2";"3";"3"));

@MailSend(AppBy;NULL;NULL;"Appraisal for " + EmName + " - Rejected by HOD.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

