@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

par.button:
REM {Get all Emp Nos directly from documents in Summary view};
_keys := @DbColumn("" : "NoCache"; @DbName; "Summary"; 1);
ExistEmp := @If(@IsError(_keys); "";
   @DbLookup("" : "NoCache"; @DbName; "Summary"; _keys; "EmNo"));
ExistEmp := @If(@IsError(ExistEmp); ""; ExistEmp);

REM {Show full picklist};
AllData := @PickList([Custom]; @DbName; "EmpList"; "Employee Master Data"; "Select a record"; 10);

REM {Check if selected Emp No already exists};
SelEmpNo := @Trim(@Word(AllData; "~"; 2));
@If(@IsMember(SelEmpNo; ExistEmp);
   @Return(@Prompt([Ok]; "Error"; "Employee " + SelEmpNo + " already exists in Summary."));
   "");

Sel1 := @Word(AllData; "~"; 1);
Sel2 := @Word(AllData; "~"; 2);
Sel3 := @Word(AllData; "~"; 3);
Sel4 := @Word(AllData; "~"; 4);
Sel5 := @Word(AllData; "~"; 5);
Sel6 := @Word(AllData; "~"; 6);
Sel7 := @Word(AllData; "~"; 7);
Sel8 := @Word(AllData; "~"; 8);

FIELD HOD := @Trim(Sel1);
FIELD EmNo := @Trim(Sel2);
FIELD EmName := @Trim(Sel3);
FIELD EmComp := @Trim(Sel4);
FIELD EmDesg := @Trim(Sel5);
FIELD EmDept := @Trim(Sel6);
FIELD EmDateJoin := @Trim(Sel7);
FIELD EmComYear := @Trim(Sel8);

@Command([ViewRefreshFields])Select
